  const RESPONSE_IMPROVEMENT_INSTRUCTION_IDS = Object.freeze(Object.keys(RESPONSE_IMPROVEMENT_INSTRUCTION_DEFS));
  const normalizeResponseImprovementProfile = value => normalizeChoice(
    String(value || '').trim().toLowerCase(),
    RESPONSE_IMPROVEMENT_PROFILES,
    DEFAULT_RESPONSE_IMPROVEMENT_PROFILE
  );
  const responseImprovementTogglesForProfile = value => {
    const profile = normalizeResponseImprovementProfile(value);
    return Object.fromEntries(RESPONSE_IMPROVEMENT_INSTRUCTION_IDS.map(id => [
      id,
      profile === 'off'
        ? false
        : profile === 'all'
          ? true
          : RESPONSE_IMPROVEMENT_INSTRUCTION_DEFS[id].recommended !== false
    ]));
  };
  const normalizeResponseImprovementToggles = (value, profile = DEFAULT_RESPONSE_IMPROVEMENT_PROFILE) => {
    let source = value;
    if (typeof source === 'string') {
      const body = source.trim();
      if (!body) source = {};
      else {
        try { source = JSON.parse(body); }
        catch (_) { source = {}; }
      }
    }
    if (!source || typeof source !== 'object' || Array.isArray(source)) source = {};
    const normalizedProfile = normalizeResponseImprovementProfile(profile);
    const fallbackProfile = normalizedProfile === 'custom' ? DEFAULT_RESPONSE_IMPROVEMENT_PROFILE : normalizedProfile;
    const out = responseImprovementTogglesForProfile(fallbackProfile);
    for (const id of RESPONSE_IMPROVEMENT_INSTRUCTION_IDS) {
      if (Object.prototype.hasOwnProperty.call(source, id)) out[id] = asBool(source[id], out[id]);
    }
    return out;
  };
  
    

  const normalizeSelectedModuleLoreIds = value => {
    let raw = value;
    if (typeof raw === 'string') {
      const body = raw.trim();
      if (!body) raw = [];
      else {
        try { raw = JSON.parse(body); }
        catch (_) { raw = body.split(/[,;\n]+/g); }
      }
    }
    if (!Array.isArray(raw)) raw = raw == null ? [] : [raw];
    const out = [];
    const seen = new Set();
    for (const item of raw) {
      const key = text(item?.id ?? item?.namespace ?? item?.key ?? item ?? '').trim();
      if (!key || seen.has(key)) continue;
      seen.add(key);
      out.push(key);
      if (out.length >= 128) break;
    }
    return out;
  };

  const normalizeExcludedCharacterLoreIds = value => {
    let raw = value;
    if (typeof raw === 'string') {
      const body = raw.trim();
      if (!body) raw = [];
      else {
        try { raw = JSON.parse(body); }
        catch (_) { raw = body.split(/[,;\n]+/g); }
      }
    }
    if (!Array.isArray(raw)) raw = raw == null ? [] : [raw];
    const out = [];
    const seen = new Set();
    for (const item of raw) {
      const key = text(item?.id ?? item?.key ?? item ?? '').trim();
      if (!key || seen.has(key)) continue;
      seen.add(key);
      out.push(key);
      if (out.length >= 2048) break;
    }
    return out;
  };

  const normalizeExcludedModuleLoreIds = value => normalizeExcludedCharacterLoreIds(value);

  const moduleSelectionKey = module => firstFilled(
    module?.id,
    module?.namespace,
    module?.name,
    module?.displayName,
    module?.__collectionKey
  );

  const moduleSelectionAliases = module => Array.from(new Set([
    moduleSelectionKey(module),
    ...identityValues(module)
  ].map(item => text(item || '').trim()).filter(Boolean)));

  const moduleLoreEntrySelectionKey = (lore = {}, sourceMeta = {}) => {
    const moduleKey = text(sourceMeta?.moduleKey || sourceMeta?.moduleId || sourceMeta?.moduleNamespace || sourceMeta?.moduleName || 'unknown-module').trim();
    const moduleScope = createTextHasher().update(`module-lore-scope:${moduleKey}`).digest();
    const explicit = firstFilled(lore?.id, lore?._id, lore?.uid, lore?.uuid);
    if (explicit) return `module-lore:${moduleScope}:id:${explicit}`;
    const signature = [
      firstFilled(lore?.comment, lore?.name, lore?.displayName),
      firstFilled(lore?.key, lore?.keys, lore?.keywords),
      firstFilled(lore?.secondkey, lore?.secondKey, lore?.secondary_keys, lore?.secondaryKeys),
      text(loreContent(lore)).trim()
    ].join('\n');
    return `module-lore:${moduleScope}:entry:${createTextHasher().update(signature).digest()}`;
  };

  const moduleSelectedForLore = (module, selectedSet) => {
    if (!module || !(selectedSet instanceof Set) || selectedSet.size === 0) return false;
    return moduleSelectionAliases(module).some(key => selectedSet.has(key));
  };

  const requiresMandatoryStageAnalysis = stageId => BEFORE_STAGE_DEFS.some(def => def.id === stageId);
  const defaultExecutionModeForStage = stageId => stageId===LIBRARIAN_STAGE_ID ? 'draft_only' : (stageId==='ariadne' ? 'draft_only' : 'analysis_draft');
  const defaultRisuReferencesForStage = (stageId) => STATE_STAGE_IDS.includes(stageId)
    ? ({ authorNote: false, persona: false, characterDescription: false, characterLorebook: false, moduleLorebook: false })
    : ({
      authorNote: stageId === 'ariadne',
      persona: true,
      characterDescription: true,
      characterLorebook: true,
      moduleLorebook: true
    });
  const normalizeRisuReferences = (value = {}, fallback = {}) => ({
    authorNote: asBool(value?.authorNote ?? value?.author_note ?? value?.include_author_note, fallback.authorNote === true),
    persona: asBool(value?.persona ?? value?.include_persona, fallback.persona === true),
    characterDescription: asBool(value?.characterDescription ?? value?.character_description ?? value?.include_character_description, fallback.characterDescription === true),
    characterLorebook: asBool(value?.characterLorebook ?? value?.character_lorebook ?? value?.include_character_lorebook, fallback.characterLorebook === true),
    moduleLorebook: asBool(value?.moduleLorebook ?? value?.module_lorebook ?? value?.include_module_lorebook, fallback.moduleLorebook === true)
  });


