    const existingCustom=String(current.beforeCustomPrompts?.librarian || '');
    const customText=options.customText===undefined?[existingCustom,...chosen.map(c=>'['+c.label+']\n'+c.text)].filter(Boolean).join('\n\n'):String(options.customText);
