        presetName: name,
        provider,
        model: result.model || preset.model,
        usage: result.usage || null,
        usageDiagnostics: providerUsageDiagnostics(result.usage || null),
        outputBudgetTokens: mode === RISUAI_AUX_MODE ? null : executionState.plan.effective.outputCap,
        invocationPlan: executionState.plan, completionEnvelope: result.completionEnvelope, execution: executionState.ledger.snapshot(),
        finishReason: result.finishReason || '',
