        await setString(cfg.auxLlm, 'thinkingType', 'aux_llm_thinking_type');
        await setString(cfg.auxLlm, 'glmThinkingType', 'aux_llm_glm_thinking', 'aux_llm_glm_thinking_type');
        await setBoolean(cfg.auxLlm, 'stream', cfg.auxLlm.stream, 'aux_llm_stream');
        const legacyEmbedProvider = await firstArgument('embed_provider');
        if (legacyEmbedProvider !== undefined)
            cfg.embed.provider = String(legacyEmbedProvider);
        const legacyEmbedUrl = await firstArgument('embed_url');
        if (legacyEmbedUrl !== undefined)
            cfg.embed.url = String(legacyEmbedUrl);
        const legacyEmbedKey = await firstArgument('embed_key');
        if (legacyEmbedKey !== undefined)
            cfg.embed.key = String(legacyEmbedKey);
        const legacyEmbedModel = await firstArgument('embed_model');
