          const aliasEvidence = { ...asObject(current?.aliasEvidence) };
          for (const alias of aliases) {
            const keyName = continuityStateNameKey(alias);
            if (keyName && !aliasEvidence[keyName]) aliasEvidence[keyName] = normalizeContinuityEvidence(current?.identityEvidence || current?.evidence) || evidence;
          }
          let aliasChanged = false;
          for (const alias of patch.aliases) {
            const keyName = continuityStateNameKey(alias);
            if (!keyName) continue;
            if (!aliases.some(value => continuityStateNameKey(value) === keyName)) {
              aliases.push(alias);
              aliasChanged = true;
            }
            aliasEvidence[keyName] = evidence;
          }
