          const name = identityChanged ? (patch.name || current?.name || id) : (current?.name || patch.name || id);
          const kindValue = identityChanged ? (patch.kind || current?.kind || 'other') : (current?.kind || patch.kind || 'other');
          const identityEvidence = identityChanged ? evidence : currentIdentityEvidence || evidence;
