          const variants=asArray(index?.slots?.[String(task.start)]?.variants);
          if(variants.some(v=>v.status==='candidate'||(v.status==='active'&&((/manual|edit/.test(string(v.origin||'')) && !['manual_cold_start','source_edit_reanalysis','manual_scan','manual_cold_start_retry'].includes(string(v.origin||'')))||v.userPinned===true))))throw new Error('수동 교정 또는 미채택 후보가 있습니다. 정본 관리에서 먼저 확인해 주세요.');
