        const manifest=await loadManifest(live.scope,buildPairs(live.chat,live.scope.scopeKey).length);
        const refs=Object.values(asObject(manifest.memories)).filter(r=>r.status==='committed' && r.artifactSchema===UNIFIED_ARTIFACT_SCHEMA && (r.embeddingStatus==='pending' || (options.retry===true&&r.embeddingStatus==='retry_pending'))).slice(0,2);
