          const currentSourceDigest = currentBatch.length === BATCH_SIZE ? sourceDigest(currentBatch) : '';
          if (currentSourceDigest && currentSourceDigest === string(failedRecord?.sourceDigest || '')) continue;
          const failedWork = await storage.getJson(key.work(context.scope, failedStart), null);
          if (string(failedWork?.runId || '') === string(failedRecord?.runId || '')) await storage.remove(key.work(context.scope, failedStart));
