          turnRange: clone(ref.turnRange || evidence.turnRange || null), sourceDigest: string(ref.sourceDigest || evidence.sourceDigest || ''),
          score, evidence, domain: string(meta.domain || ''), entity: compact(meta.entity || '', 180), field: compact(meta.field || '', 100), dimension: compact(meta.dimension || '', 80)
