      if (controller) {
        guard.deadlineTimer = setTimeout(() => {
          if (!controller.signal.aborted) controller.abort(sgaGuardError('LIBRA_SGA_DEADLINE', 'GRADIA provider wall-time budget exhausted.'));
        }, maxWallMs);
      }
      const normalPlan={};
      for(const stageId of enabledStages){
        if(normalizeMultiPipelineMode(settings?.multiPipelineMode)==='heavyweight')normalPlan[`${stageId}:sga_private_analysis`]=1;
        normalPlan[`${stageId}:${stageId===SGA_SHADOW_STAGE_ID?'sga_full_draft':'sga_patch'}`]=1;
      }
      if(settings?.outputMode==='risu_engine')normalPlan['*:sga_final_rewrite']=1;
      if(settings?.sgaSemanticValidationEnabled!==false && Number(settings?.sgaValidationRecoveryAttempts ?? 1)>0)normalPlan['*:sga_length_rewrite']=1;
      guard.consumerOperation=createConsumerOperation({group:'gradia',settings,normalPlan,scopeKey:context?.scope?.scopeKey||'',signal:guard.signal,validate:()=>assertConsumerEvidenceCurrent(evidencePacket)});
      guard.settingsSnapshot=settings;
