  const memoryStageEnabledForSettings = (settings={},stageName='') => stageName===LIBRARIAN_STAGE_ID && settings.enableLibrarian!==false && settings.mode!=='off';

  const activeMemoryStageOrderForSettings = settings => LibraMemoryCore.STAGE_ORDER.filter(stageName => memoryStageEnabledForSettings(settings, stageName));

  const runLibraMemoryPipeline = async (job = {}) => {
    if(job.engineVersion!==LIBRARIAN_ENGINE_VERSION)throw retiredAnalyzerError(job.engineVersion || 'legacy');
    const stages = [];
    const optionalFailures = [];
    const skippedStages = [];
    let currentStage = job.currentStage || null;
    const startIndex = Math.max(0, Number(job.startIndex || 0));
    const pipelineSettings = job.settings || await loadSettings().catch(() => Runtime.settings || {});
    const activeStageOrder = activeMemoryStageOrderForSettings(pipelineSettings);
    if (!activeStageOrder.includes(LIBRARIAN_STAGE_ID) && !stageDraft(currentStage)) {
      throw new Error('Librarian이 비활성화되어 기억 분석을 시작할 수 없습니다.');
    }
    for (let index = startIndex; index < LibraMemoryCore.STAGE_ORDER.length; index += 1) {
      const stageName = LibraMemoryCore.STAGE_ORDER[index];
      if (!memoryStageEnabledForSettings(pipelineSettings, stageName)) {
        const skipped = {
          index,
          stage: stageName,
          label: LibraMemoryCore.STAGE_LABELS[stageName] || stageName,
          reason: 'stage_disabled_by_advanced_settings',
          at: new Date().toISOString()
        };
        skippedStages.push(skipped);
        recordStageTrace({
          stage: stageName, ok: true, skipped: true, disabled: true, reason: skipped.reason,
          memoryMode: true, systemPrompt: '', userPrompt: '', rawResponse: '', parsed: null, elapsedMs: 0
        });
        await job.onStageSkip?.({ index, stageName, skipped, currentStage, stages: stages.slice(), optionalFailures: optionalFailures.slice(), activeStageOrder: activeStageOrder.slice() });
        continue;
      }
      await job.onStageStart?.({ index, stageName, currentStage, stages: stages.slice(), optionalFailures: optionalFailures.slice(), activeStageOrder: activeStageOrder.slice() });
      try {
        if (job.signal?.aborted) throw new DOMException('Canonical job cancelled.', 'AbortError');
        const execute = LibraMemoryCore.executeUnifiedStage;
        const outcome = await execute(stageName, job.batch || [], currentStage, { signal: job.signal, providerBudget: job.providerBudget, unifiedBasis:job.unifiedBasis, policySnapshot:pipelineSettings,validateRecoverySource:job.validateRecoverySource });
        currentStage = outcome?.stage || currentStage;
        if (!currentStage) throw new Error(`LIBRA ${stageName} returned no stage result.`);
        stages.push(currentStage);
        await job.onStageComplete?.({ index, stageName, outcome, currentStage, stages: stages.slice(), optionalFailures: optionalFailures.slice(), activeStageOrder: activeStageOrder.slice() });
      } catch (error) {
        if (stageName === LIBRARIAN_STAGE_ID || !stageDraft(currentStage) || error?.name === 'AbortError' || job.signal?.aborted) throw error;
        const failure = {
          index, stage: stageName, label: LibraMemoryCore.STAGE_LABELS[stageName] || stageName,
          message: String(error?.message || error || 'ito_failed'), at: new Date().toISOString()
        };
        optionalFailures.push(failure);
        await job.onStageFailure?.({ index, stageName, error, failure, currentStage, stages: stages.slice(), optionalFailures: optionalFailures.slice(), activeStageOrder: activeStageOrder.slice() });
      }
    }
    return {
      ok: !!stageDraft(currentStage),
      memoryMode: true,
      partial: optionalFailures.length > 0,
      optionalFailures,
      skippedStages,
      activeStageOrder,
      stages,
      currentStage,
      finalDraft: stageDraft(currentStage)
    };
  };

  const observeHookRuntime = (kind, type = '') => {
    const at = Date.now();
    const runtime = Runtime.hookRuntime || (Runtime.hookRuntime = {
      installedAt: at, requestHooksObservedSinceInstall: 0, modelRequestsObservedSinceInstall: 0,
      firstBeforeRequestAt: 0, firstAfterRequestAt: 0, firstOutputAt: 0,
      beforeRequestRuns: 0, afterRequestRuns: 0, outputRuns: 0, lastRequestType: '', lastOutputMode: ''
    });
    const normalizedType = normalizeRequestType(type) || String(type || '').trim().toLowerCase() || 'missing';
    runtime.requestHooksObservedSinceInstall = Math.max(0, Number(runtime.requestHooksObservedSinceInstall || 0)) + 1;
    runtime.lastRequestType = normalizedType;
    if (kind === 'before' && normalizedType === 'model') runtime.modelRequestsObservedSinceInstall = Math.max(0, Number(runtime.modelRequestsObservedSinceInstall || 0)) + 1;
    if (kind === 'before') {
      runtime.beforeRequestRuns = Math.max(0, Number(runtime.beforeRequestRuns || 0)) + 1;
      if (!runtime.firstBeforeRequestAt) runtime.firstBeforeRequestAt = at;
    } else if (kind === 'after') {
      runtime.afterRequestRuns = Math.max(0, Number(runtime.afterRequestRuns || 0)) + 1;
      if (!runtime.firstAfterRequestAt) runtime.firstAfterRequestAt = at;
    } else if (kind === 'output') {
      runtime.outputRuns = Math.max(0, Number(runtime.outputRuns || 0)) + 1;
      runtime.lastOutputMode = String(type || 'output');
      if (!runtime.firstOutputAt) runtime.firstOutputAt = at;
    }
    return runtime;
  };

  const hookRuntimeSnapshot = () => {
    const runtime = Runtime.hookRuntime || {};
    const beforeRuns = Math.max(0, Number(runtime.beforeRequestRuns || 0));
    const afterRuns = Math.max(0, Number(runtime.afterRequestRuns || 0));
    const outputRuns = Math.max(0, Number(runtime.outputRuns || 0));
    const status = beforeRuns || afterRuns || outputRuns
      ? 'request_pipeline_observed'
      : 'installed_no_host_activity';
    return {
      ...runtime,
      ageMs: Math.max(0, Date.now() - Number(runtime.installedAt || Date.now())),
      beforeRequestRuns: beforeRuns,
      afterRequestRuns: afterRuns,
      outputRuns,
      status
    };
  };

  const beforeRequest = async (messages, type) => {
    if (LibraMemoryCore.state.disposed) return messages;
    observeHookRuntime('before', type);
    return await LibraMemoryCore.beforeRequest(messages, type);
  };
  const afterRequestReuseCleanup = async (response, type) => {
    if (LibraMemoryCore.state.disposed) return response;
    observeHookRuntime('after', type);
    return await LibraMemoryCore.afterRequest(response, type);
  };



