      ariadne: 'Ariadne', character_ito: '인물 ito', world_ito: '세계 ito', plot_ito: '플롯 ito',
      [SGA_SHADOW_STAGE_ID]: 'SHADOW', [SGA_CHARACTER_AIDE_STAGE_ID]: '인물 AIDE',
