        const path = promptStudioOocTargetPath(domain, profileName, stage.id, definition.id);
        const container = profile ? promptStudioOocSectionContainer(profile, { domain, stageId: stage.id }) : null;
        const override = normalizePromptSectionOverride(container?.[definition.id] || {});
