    const status = guiAsObject(view?.domainStatus?.[domainKey]);
    const reviewedTurn = Number(status.reviewedThrough || status.throughTurn || view?.throughTurn || 0);
    const changedTurn = Number(row?.correctionProvenance?.anchor?.throughTurn || row?.changedThrough || row?.changedThroughTurn || row?.updatedThroughTurn || evidence.changedThrough || evidence.turn || Math.max(0,...Object.values(guiAsObject(row?.fieldEvidence)).flatMap(e=>guiAsArray(e?.evidenceSpans).map(span=>Number(/^t(\d+)-/.exec(span.ref||'')?.[1]||0)))));
    const facts = worldManagerArticleFacts(detail,view);
    const state = detail?.state && typeof detail.state === 'object' ? detail.state : {};
    const lead = worldManagerArticleValue(detail?.summary || row?.summary || state.summary || state.description || state.value || (typeof detail?.state === 'string' ? detail.state : ''));
    const fieldEvidence=guiAsObject(row?.fieldEvidence||detail?.fieldEvidence);
    const quotes=[...new Set(Object.values(fieldEvidence).flatMap(e=>guiAsArray(e?.evidenceSpans).map(span=>span.quote)).filter(Boolean))];
    const evidenceText = worldManagerArticleValue(evidence.summary || evidence.snippet || evidence.text || quotes.join('\n') || evidence.source || provenance.source || '');
    const cleared=[...new Set([...Object.keys(guiAsObject(row?.clearedFieldEvidence)),...Object.keys(guiAsObject(row?.clearedFieldCorrectionProvenance))])];
    const pending=guiAsArray(view?.head?.unifiedApplied?.pending).filter(p=>p.recordId===row?.id);
    const memoryId = text(evidence.memoryId || provenance.memoryId || row?.memoryId || '');
