        guiEl('span', { text: changedTurn > 0 ? `마지막 실제 변경 T${changedTurn}` : '마지막 실제 변경 근거 미제공' }),
        guiEl('span', { text: reviewedTurn > 0 ? `정본 검토 기준 T${reviewedTurn}` : '검토 기준 대기' })
