    getProviderDebug() {
      return redactPublicSecrets(safeClone({
        request: Runtime.lastProviderRequest,
        response: Runtime.lastProviderResponse,
        error: Runtime.lastProviderError,
        backendBridge: Runtime.lastBackendBridge
      }));
    },
