    async saveCanonicalManualStateDisposition(options = {}) { return await LibraMemoryCore.saveCanonicalManualStateDisposition(options); },
    async saveContinuityOverride(options = {}) { return await LibraMemoryCore.saveContinuityOverride(options); },
    narrativeCompletionSchema: 'libra.narrative_completion.v2',
    migrateStoryArcToNarrativeIfNeeded: async options => safeClone(await migrateStoryArcToNarrativeIfNeeded(options || {})),
    validateAndBindNarrativePatchEvidence: (patch, sourceContext = null) => safeClone(validateAndBindNarrativePatchEvidence(patch, sourceContext)),
    callNarrativeDeltaProvider: async options => safeClone(await callNarrativeDeltaProvider(options || {})),
    narrativeStatePromptBlock: (narrative, audience = 'planner') => narrativeStatePromptBlock(narrative, audience),
    plannerNarrativeDirectionPromptBlock: direction => plannerNarrativeDirectionPromptBlock(direction),
    async getPlannerNarrativeDirection(options = {}) { return safeClone(await getPlannerNarrativeDirection(options)); },
    async setPlannerNarrativeDirection(value = {}, options = {}) { return safeClone(await setPlannerNarrativeDirection(value, options)); },
    async clearPlannerNarrativeDirection(options = {}) { return safeClone(await clearPlannerNarrativeDirection(options)); },
    async getWorldManagerCorrections() { const context=await LibraMemoryCore.resolveContext(); return safeClone(await LibraMemoryCore.loadStateCorrectionJournal(context.scope)); },
    async listWorldManagerHistory(options = {}) { return safeClone(await LibraMemoryCore.listWorldManagerHistory(options)); },
    async getWorldManagerHistoryDetail(options = {}) { return safeClone(await LibraMemoryCore.getWorldManagerHistoryDetail(options)); },
    async listWorldManagerCorrections(options = {}) { return safeClone(await LibraMemoryCore.listWorldManagerCorrections(options)); },
    async getWorldManagerRuntimeMeta() { return safeClone(await LibraMemoryCore.getWorldManagerRuntimeMeta()); },
    async getWorldManagerNarrative() {
      const snapshot = await LibraMemoryCore.refreshSnapshot(undefined, { suppressGuiSchedule: true });
      return safeClone(snapshot?.continuityState?.narrative || __libraNarrativeEmptyState());
    },
    async addWorldManagerCorrection(options = {}) { return safeClone(await LibraMemoryCore.appendStateCorrection(options)); },
    async addWorldManagerNarrativeCorrection(narrativePatch = {}, options = {}) {
      return safeClone(await LibraMemoryCore.appendStateCorrection({ ...options, target: { domain: 'narrative', mode: 'narrative_patch' }, patch: { narrative: safeClone(narrativePatch) } }));
    },
    async setWorldManagerCorrectionStatus(correctionId, status) { return safeClone(await LibraMemoryCore.setStateCorrectionStatus(correctionId, status)); },
    async setWorldManagerNarrativeCorrectionStatus(correctionId, status) { return safeClone(await LibraMemoryCore.setStateCorrectionStatus(correctionId, status)); },
