    await new Promise(resolve => setTimeout(resolve, 25));
    const second = await inspect();
    if (first !== second) throw new Error('LIBRA registry-only shell changed during owner verification');
    const [pluginKeys, localKeys] = await Promise.all([
      MemorySuiteStorageBridge.ownerLegacyKeys('plugin', true),
      MemorySuiteStorageBridge.ownerLegacyKeys('local', true).catch(() => [])
    ]);
    if (pluginKeys.some(key => key.startsWith(physicalPrefix))) throw new Error('LIBRA registry-only shell has local pluginStorage records');
    if (localKeys.some(key => key.includes(scopeKey))) throw new Error('LIBRA registry-only shell has associated local vector records');
    const scope = { scopeId: scopeKey, scopeKey, label: scopeKey, aliases: [] };
    const beforeMode = await MemorySuiteStorageBridge.getScopeMode(scope);
    if (beforeMode?.mode === 'server_only') throw new Error('LIBRA registry-only cleanup is blocked in server_only mode');
    if (beforeMode?.mode !== 'plugin_only') await MemorySuiteStorageBridge.setScopeMode(scope, 'plugin_only');
    if ((await MemorySuiteStorageBridge.getScopeMode(scope))?.mode !== 'plugin_only') throw new Error('LIBRA registry-only plugin_only transition failed');
