    if (removed) await MemorySuiteStorageBridge.ownerLegacyWrite('plugin', registryKey, typeof raw === 'string' ? JSON.stringify(registry) : registry);
    const readback = parseLibraOwnerValue(await MemorySuiteStorageBridge.ownerLegacyRead('plugin', registryKey));
